mapper.update:
UPDATE quant_strategy_position_rebuild_inventory
SET open_quantity=#{quantity},cost_basis=#{cost},cycle_number=#{cycleNumber},cycle_id=#{cycleId},
    last_trade_time=#{tradeTime},last_trade_id=#{tradeId}
WHERE run_id=#{runId} AND strategy_instance_id=#{instanceId} AND position_side=#{side}
  AND strategy_id=#{strategyId}

mapper.select:
SELECT symbol,exchange_trade_id,exchange_order_id,strategy_id,strategy_instance_id,cycle_id,position_side,
       fill_role,exchange_side,quantity,fill_price,commission,commission_asset,realized_pnl,trade_time
FROM quant_strategy_position_rebuild_fill
WHERE run_id=#{runId}
  AND (
    #{afterTradeTime} IS NULL
    OR trade_time>#{afterTradeTime}
    OR (trade_time=#{afterTradeTime} AND exchange_trade_id>#{afterTradeId})
  )
ORDER BY trade_time ASC,exchange_trade_id ASC
LIMIT #{limit}
